#!/usr/bin/env node
// Slack Web API thin client for agents.
// Usage: node slack_request.cjs <api-method> ['{"json":"body"}']
// Reads SLACK_TOKEN (or SLACK_BOT_TOKEN) from the environment.
// Exit codes: 0 = ok:true | 1 = transport/HTTP failure | 2 = usage/auth/config error.
// Prints response JSON on stdout; diagnostics go to stderr. Requires Node 18+ (global fetch).
'use strict';

const BASE_URL = 'https://slack.com/api/';
const MAX_RETRIES = 3; // retries for 429 and transient 5xx
const MAX_PRINT = 20000; // protect the agent context window

function usage(message) {
  if (message) console.error('Error: ' + message);
  console.error('Usage: node slack_request.cjs <api-method> [json-body]');
  console.error("Example: node slack_request.cjs chat.postMessage '{\"channel\":\"C123\",\"text\":\"hi\"}'");
  console.error('Environment: set SLACK_TOKEN (bot xoxb- or user xoxp- token).');
  process.exit(2);
}

const args = process.argv.slice(2);
if (args.length < 1 || args.length > 2) {
  usage(args.length > 2 ? 'too many arguments' : 'missing api-method');
}
const [method, jsonBody] = args;
if (!/^[a-z][a-z0-9._]*$/.test(method)) usage('invalid method name: ' + method);

let payload;
if (jsonBody !== undefined) {
  try {
    payload = JSON.parse(jsonBody);
  } catch {
    usage('json-body is not valid JSON: ' + jsonBody.slice(0, 120));
  }
}

const token = process.env.SLACK_TOKEN || process.env.SLACK_BOT_TOKEN || '';
if (!token) usage('SLACK_TOKEN is not set; export it first (e.g. export SLACK_TOKEN=xoxb-...)');

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function main() {
  let failure = '';
  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
    const headers = { Authorization: 'Bearer ' + token, Accept: 'application/json' };
    const hasBody = payload !== undefined;
    const res = await fetch(BASE_URL + method, {
      method: hasBody ? 'POST' : 'GET',
      headers: hasBody ? Object.assign(headers, { 'Content-Type': 'application/json; charset=utf-8' }) : headers,
      body: hasBody ? JSON.stringify(payload) : undefined,
    });
    const raw = await res.text();
    let json = null;
    try { json = JSON.parse(raw); } catch {}

    if (res.status === 429 && attempt < MAX_RETRIES) {
      const wait = Number(res.headers.get('retry-after')) || 1;
      console.error('Rate limited (429); retrying in ' + wait + 's...');
      await sleep(wait * 1000);
      continue;
    }
    if (res.status >= 500 && attempt < MAX_RETRIES) {
      console.error('Transient HTTP ' + res.status + '; retrying...');
      await sleep(1000 * (attempt + 1));
      continue;
    }
    if (!res.ok) {
      failure = 'HTTP ' + res.status + ': ' + (json && json.error ? json.error : raw.slice(0, 300));
      break;
    }
    if (json === null) {
      failure = 'Non-JSON response: ' + raw.slice(0, 300);
      break;
    }
    if (json.ok !== true) {
      failure = 'Slack error: ' + (json.error || 'unknown') + (json.warning ? ' (warning: ' + json.warning + ')' : '');
      break;
    }
    const out = JSON.stringify(json, null, 2);
    console.log(out.length > MAX_PRINT ? out.slice(0, MAX_PRINT) + '\n...[output truncated]' : out);
    process.exit(0);
  }
  console.error(failure || 'Request failed');
  process.exit(1);
}

main().catch((err) => {
  console.error('Request failed: ' + (err && err.message ? err.message : String(err)));
  process.exit(1);
});

#!/usr/bin/env node
// Task-local validator + packager for the slack-api skill.
// Mirrors skill-creator's validate_skill.cjs rules, then packages the folder
// into a .skill zip archive (store method, entries at archive root) matching
// `zip -r out.skill .` behavior, and verifies the archive by re-reading it.
// Usage: node package_slack_api.cjs [skill-folder] [output-file]
'use strict';

const fs = require('node:fs');
const path = require('node:path');

const SKILL_DIR = path.resolve(process.argv[2] || 'slack-api');
const OUT_FILE = path.resolve(process.argv[3] || 'slack-api.skill');
const SKILL_NAME = path.basename(SKILL_DIR);

const fail = (msg) => { console.error('FAIL: ' + msg); process.exit(1); };

function walkFiles(dir, base, out) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const abs = path.join(dir, entry.name);
    if (entry.isDirectory()) walkFiles(abs, base, out);
    else out.push(path.relative(base, abs).split(path.sep).join('/'));
  }
  return out;
}

// ---- Validation (mirrors validate_skill.cjs) ----
if (!fs.existsSync(SKILL_DIR) || !fs.statSync(SKILL_DIR).isDirectory()) {
  fail('path is not a directory: ' + SKILL_DIR);
}
const skillMdPath = path.join(SKILL_DIR, 'SKILL.md');
if (!fs.existsSync(skillMdPath)) fail('SKILL.md not found');
const md = fs.readFileSync(skillMdPath, 'utf8');
if (!md.startsWith('---')) fail('no YAML frontmatter found');
const parts = md.split('---');
if (parts.length < 3) fail('invalid frontmatter format');
const frontmatter = parts[1];
const nameMatch = frontmatter.match(/^name:\s*(.+)$/m);
const descMatch = frontmatter.match(/^description:\s*(?:'([^']*)'|"([^"]*)"|(.+))$/m);
if (!nameMatch) fail('missing "name" in frontmatter');
if (!descMatch) fail('description must be a single-line string: description: ...');
const name = nameMatch[1].trim();
const description = (descMatch[1] !== undefined ? descMatch[1] : descMatch[2] !== undefined ? descMatch[2] : descMatch[3] || '').trim();
if (description.includes('\n')) fail('description must be a single line (no newlines)');
if (!/^[a-z0-9-]+$/.test(name)) fail('name "' + name + '" should be hyphen-case');
if (name !== SKILL_NAME) fail('folder name "' + SKILL_NAME + '" must equal frontmatter name "' + name + '"');
if (description.length > 1024) fail('description is too long (max 1024 chars), got ' + description.length);
if (description.length < 40) fail('description is too short to be informative');

const allFiles = walkFiles(SKILL_DIR, SKILL_DIR, []);
if (allFiles.length === 0) fail('skill folder is empty');
for (const rel of allFiles) {
  const content = fs.readFileSync(path.join(SKILL_DIR, rel), 'utf8');
  if (content.includes('TODO:')) fail('unresolved TODO: found in ' + rel);
  const base = path.basename(rel);
  if (/^example_/.test(base) || ['README.md', 'INSTALLATION_GUIDE.md', 'QUICK_REFERENCE.md', 'CHANGELOG.md'].includes(base)) {
    fail('example/junk file must be removed: ' + rel);
  }
}
// References inside SKILL.md must resolve to real files
const body = parts.slice(2).join('---');
for (const ref of body.matchAll(/(scripts|references|assets)\/[A-Za-z0-9_./-]+/g)) {
  const rel = ref[0].replace(/[.),;\]]+$/, '');
  if (!allFiles.includes(rel)) fail('SKILL.md references missing file: ' + rel);
}
console.log('Validated ' + SKILL_NAME + ' (' + allFiles.length + ' files, frontmatter ok, no TODOs, references ok)');

// ---- ZIP writer (store method, no compression, UTF-8 flags) ----
const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();
function crc32(buf) {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}
const u16 = (n) => Buffer.from([n & 255, (n >>> 8) & 255]);
const u32 = (n) => Buffer.from([n & 255, (n >>> 8) & 255, (n >>> 16) & 255, (n >>> 24) & 255]);
const SIG_LOCAL = Buffer.from([0x50, 0x4b, 0x03, 0x04]);
const SIG_CENTRAL = Buffer.from([0x50, 0x4b, 0x01, 0x02]);
const SIG_EOCD = Buffer.from([0x50, 0x4b, 0x05, 0x06]);
const DOS_DATE = 0x21; // 1980-01-01, a valid MS-DOS date
const FLAG_UTF8 = 0x0800;

const entries = allFiles.slice().sort();
const locals = [];
const centrals = [];
let localOffset = 0;
for (const rel of entries) {
  const data = fs.readFileSync(path.join(SKILL_DIR, rel));
  const nameBuf = Buffer.from(rel, 'utf8');
  const crc = crc32(data);
  locals.push(Buffer.concat([
    SIG_LOCAL, u16(20), u16(FLAG_UTF8), u16(0), u16(0), u16(DOS_DATE),
    u32(crc), u32(data.length), u32(data.length), u16(nameBuf.length), u16(0),
    nameBuf, data,
  ]));
  centrals.push(Buffer.concat([
    SIG_CENTRAL, u16(0x0314), u16(20), u16(FLAG_UTF8), u16(0), u16(0), u16(DOS_DATE),
    u32(crc), u32(data.length), u32(data.length), u16(nameBuf.length), u16(0), u16(0),
    u16(0), u16(0), u32(0o100644 << 16), u32(localOffset),
    nameBuf,
  ]));
  localOffset += locals[locals.length - 1].length;
}
const cdStart = localOffset;
const cdSize = centrals.reduce((s, b) => s + b.length, 0);
const eocd = Buffer.concat([
  SIG_EOCD, u16(0), u16(0), u16(entries.length), u16(entries.length),
  u32(cdSize), u32(cdStart), u16(0),
]);
const archive = Buffer.concat([...locals, ...centrals, eocd]);
fs.writeFileSync(OUT_FILE, archive);

// ---- Verification: re-parse the archive we just wrote ----
const buf = fs.readFileSync(OUT_FILE);
let eocdPos = -1;
for (let i = buf.length - 22; i >= Math.max(0, buf.length - 22 - 65535); i--) {
  if (buf[i] === 0x50 && buf[i + 1] === 0x4b && buf[i + 2] === 0x05 && buf[i + 3] === 0x06) { eocdPos = i; break; }
}
if (eocdPos < 0) fail('verification: EOCD not found in ' + OUT_FILE);
const total = buf.readUInt16LE(eocdPos + 10);
const cdOff = buf.readUInt32LE(eocdPos + 16);
if (total !== entries.length) fail('verification: expected ' + entries.length + ' entries, found ' + total);
let p = cdOff;
let checked = 0;
for (let n = 0; n < total; n++) {
  if (buf.readUInt32LE(p) !== 0x02014b50) fail('verification: bad central directory signature at entry ' + n);
  const nameLen = buf.readUInt16LE(p + 28);
  const extraLen = buf.readUInt16LE(p + 30);
  const method = buf.readUInt16LE(p + 10);
  const crc = buf.readUInt32LE(p + 16);
  const size = buf.readUInt32LE(p + 24);
  const localOff = buf.readUInt32LE(p + 42);
  const relName = buf.toString('utf8', p + 46, p + 46 + nameLen);
  if (method !== 0) fail('verification: entry ' + relName + ' is compressed (method ' + method + ')');
  const lNameLen = buf.readUInt16LE(localOff + 26);
  const lExtraLen = buf.readUInt16LE(localOff + 28);
  const dataStart = localOff + 30 + lNameLen + lExtraLen;
  const dataCrc = crc32(buf.subarray(dataStart, dataStart + size));
  if (dataCrc !== crc) fail('verification: CRC mismatch for ' + relName);
  if (!entries.includes(relName)) fail('verification: unexpected entry ' + relName);
  checked++;
  p += 46 + nameLen + extraLen;
}
if (checked !== entries.length) fail('verification: checked ' + checked + ' of ' + entries.length + ' entries');
console.log('Packaged ' + OUT_FILE + ': ' + entries.length + ' entries, ' + buf.length + ' bytes, all CRCs verified');
for (const rel of entries) console.log('  - ' + rel);

'use strict';

/*
 * build_slack_api_skill.cjs
 *
 * Task-local builder for the requested Slack API skill. Creates the skill
 * folder structure (SKILL.md + scripts/slack_request.cjs) under the current
 * working directory, smoke-tests the helper script, and packages the skill
 * with the skill-creator package_skill.cjs when it is available.
 */

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const ROOT = process.cwd();
const SKILL_NAME = 'slack-api';
const SKILL_DIR = path.join(ROOT, SKILL_NAME);

const skillMarkdown = String.raw`---
name: slack-api
description: "Send messages, ephemeral messages, thread replies, and reactions, upload files, and read conversations, users, and history through Slack's Web API and Incoming Webhooks. Use when a user asks to automate Slack notifications, query Slack workspace activity, or perform Slack actions with a bot token, user token, or webhook URL."
---

# Slack API

Use Slack's Web API (base URL https://slack.com/api/) and Incoming Webhooks to send and read workspace messages. The bundled script scripts/slack_request.cjs performs one authenticated request so the HTTP code does not get rewritten every time. For multi-step work (resolve an ID, then act, then page through results) call the script once per step.

## Credentials and identifiers

- Bot tokens start with xoxb-; user tokens start with xoxp-. Prefer a bot token with the smallest scope set that still works.
- Read tokens from environment variables (SLACK_TOKEN, SLACK_BOT_TOKEN, SLACK_WEBHOOK_URL) or ask the user. Never hard-code a token in a file and never print a full token.
- Channel IDs start with C..., user IDs with U..., file IDs with F..., team IDs with T....
- A message timestamp (ts) such as 1700000000.123456 identifies a message and doubles as thread_ts for replies.

## Request helper

The helper needs Node.js 18+ and has no third-party dependencies. From the skill folder run:

    node scripts/slack_request.cjs --endpoint chat.postMessage --token "$SLACK_TOKEN" --payload '{"channel":"C1234567890","text":"Hello from a bot"}'

Send through an Incoming Webhook:

    node scripts/slack_request.cjs --webhook-url "$SLACK_WEBHOOK_URL" --payload '{"text":"Hello"}'

Flags: --endpoint (Web API method; default chat.postMessage), --token, --webhook-url, --payload, --payload-file. The payload may also be piped on stdin. On success the script prints Success: followed by trimmed JSON (webhooks answer with plain text). On failure it prints a concise reason and exits non-zero: 1 means usage, transport, or HTTP error; 2 means Slack answered ok:false; 75 means rate limited (retry after the Retry-After seconds Slack reports).

## Common operations

Post a message: chat.postMessage with a channel ID and text. Add link_names: true to turn plain @name and #channel text into links; pass blocks for rich layouts. Plain text is preferred over attachments.

Reply in a thread: set thread_ts to the parent message ts. The response carries reply_ts so later replies can chain.

Send an ephemeral message: chat.postEphemeral with channel, user, and text; only that user sees it.

Update or delete a message: chat.update or chat.delete with channel and ts.

Resolve a channel name to an ID: conversations.list with types "public_channel,private_channel" and limit 1000, paging with cursor from response_metadata.next_cursor until the name matches. Needs channels:read and groups:read. When the app is already in the channel, conversations.info with the channel ID is cheaper.

Find a user: users.lookupByEmail with email (scope users:read.email), or page users.list with limit 1000. User IDs are stable; emails and display names are not.

Read history: conversations.history with channel and limit, plus optional oldest and latest (Unix seconds) to bound the window. Messages carry ts, user, text, and subtype for special kinds; page with next_cursor.

React to a message: reactions.add with channel, name (no colons), and timestamp; reactions.remove works the same way.

Search messages: search.messages with query (scope search:read).

Upload a file: files.upload is deprecated. Call files.getUploadURLExternal with filename and length to get upload_url and file_id, POST the raw bytes to upload_url (for example curl -F file=@report.csv "upload_url"), then call files.completeUploadExternal with files: [{"id":"F...","title":"report.csv"}]. Scope: files:write.

Open a modal: views.open with a view object and the trigger_id from an interaction.

## Message formatting

Slack uses mrkdwn: *bold*, _italic_, ~strikethrough~, and code spans wrapped in the single back-tick character. Mention a user with <@U123...>, reference a channel with <#C123...>, and hyperlink with <https://example.com|link text>. Set link_names: true to link plain @name and #channel text.

## Responses and errors

Web API responses set ok to true or false. Treat ok:false as a failure and surface the error string. Common errors:

- invalid_auth, not_authed, account_inactive: token wrong, revoked, or from a deleted app; ask for a fresh one.
- missing_scope: add the scope to the app and reinstall it in the workspace.
- channel_not_found: use the channel ID, not the name, and confirm the app is in the channel.
- not_in_channel: join public channels with conversations.join or ask an admin to invite the app.
- is_archived: pick a channel that is not archived.
- msg_too_long: text is limited to 40,000 characters; split the message or trim it.
- rate_limited: HTTP 429 with Retry-After; wait that many seconds and retry (the helper exits 75).

Pagination: methods return up to 100 to 1000 records per page (see the method docs) plus response_metadata.next_cursor. Keep paging while the cursor is non-empty and stop once the user's requested volume is reached.

Rate limits: roughly one request per second per method. Delay briefly between calls in a loop and always honor Retry-After on 429.

## Typical multi-step flow

1. Resolve targets first: look up channel and user IDs once and reuse them.
2. Perform the action with IDs.
3. Page only as far as needed and summarize counts instead of dumping full lists.
4. Report what was done: channel, message ts, and any failures.

## Scope checklist

chat:write to send, update, and delete messages; chat:write.customize for bot name and icon overrides; channels:read and groups:read for conversation metadata; im:read and mpim:read for DM and group history; users:read and users:read.email for member lookup; reactions:write; files:write for uploads; search:read for search.messages; incoming-webhook when using a webhook URL.
`;

const helperSource = String.raw`#!/usr/bin/env node
/*
 * slack_request.cjs - one Slack request with LLM-friendly output.
 * Bundled with the slack-api skill. Requires Node.js 18+ (global fetch).
 * No third-party dependencies.
 *
 * Usage:
 *   node scripts/slack_request.cjs --endpoint chat.postMessage \
 *       --token "$SLACK_TOKEN" \
 *       --payload '{"channel":"C1234567890","text":"Hello"}'
 *   node scripts/slack_request.cjs --webhook-url "$SLACK_WEBHOOK_URL" \
 *       --payload '{"text":"Hello"}'
 *   node scripts/slack_request.cjs --endpoint conversations.history \
 *       --token "$SLACK_TOKEN" --payload-file history.json
 *   echo '{"channel":"C1234567890","text":"hi"}' | node scripts/slack_request.cjs \
 *       --token "$SLACK_TOKEN"
 *
 * Exit codes: 0 success; 1 usage/transport/HTTP error; 2 Slack API error
 * (ok:false); 75 rate limited (retry after the reported Retry-After seconds).
 */
'use strict';

const fs = require('fs');
const path = require('path');

function usageError(message) {
  process.stderr.write('Error: ' + message + '\n');
  process.stderr.write('Usage: node slack_request.cjs (--token TOKEN | --webhook-url URL) [--endpoint METHOD] (--payload JSON | --payload-file FILE | stdin)\n');
  process.exit(1);
}

function parseArgs(argv) {
  const options = { endpoint: 'chat.postMessage', payload: null, payloadFile: null, token: null, webhookUrl: null };
  for (let i = 0; i < argv.length; i = i + 1) {
    const flag = argv[i];
    const nextValue = function () {
      i = i + 1;
      if (i >= argv.length) usageError('Missing value for ' + flag);
      return argv[i];
    };
    if (flag === '--endpoint') options.endpoint = nextValue();
    else if (flag === '--token') options.token = nextValue();
    else if (flag === '--webhook-url') options.webhookUrl = nextValue();
    else if (flag === '--payload') options.payload = nextValue();
    else if (flag === '--payload-file') options.payloadFile = nextValue();
    else usageError('Unknown flag: ' + flag);
  }
  return options;
}

function readPayload(options) {
  if (options.payload !== null && options.payloadFile !== null) {
    usageError('Use either --payload or --payload-file, not both');
  }
  let raw = options.payload;
  if (options.payloadFile !== null) {
    try {
      raw = fs.readFileSync(path.resolve(options.payloadFile), 'utf8');
    } catch (error) {
      usageError('Could not read payload file: ' + error.message);
    }
  } else if (raw === null) {
    if (process.stdin.isTTY) {
      usageError('No payload provided; pass --payload JSON, --payload-file FILE, or pipe JSON on stdin');
    }
    try {
      raw = fs.readFileSync(0, 'utf8');
    } catch (error) {
      usageError('Could not read stdin payload: ' + error.message);
    }
  }
  if (raw === null || raw.trim().length === 0) usageError('Payload is empty');
  try {
    return JSON.parse(raw);
  } catch (error) {
    usageError('Payload is not valid JSON: ' + error.message);
  }
}

function trimOutput(text, maxLines, maxChars) {
  if (maxLines === undefined) maxLines = 60;
  if (maxChars === undefined) maxChars = 6000;
  const allLines = String(text).split('\n');
  let result = allLines.slice(0, maxLines).join('\n');
  if (allLines.length > maxLines) {
    result = result + '\n... (' + (allLines.length - maxLines) + ' more lines)';
  }
  if (result.length > maxChars) {
    result = result.slice(0, maxChars) + '\n... (output truncated)';
  }
  return result;
}

async function main() {
  const options = parseArgs(process.argv.slice(2));
  const token = options.token || process.env.SLACK_TOKEN || process.env.SLACK_BOT_TOKEN || '';
  const webhookUrl = options.webhookUrl || process.env.SLACK_WEBHOOK_URL || '';

  if (token === '' && webhookUrl === '') {
    usageError('Provide --token (or set SLACK_TOKEN) for the Web API, or --webhook-url (or set SLACK_WEBHOOK_URL) for a webhook');
  }
  if (token !== '' && webhookUrl !== '') {
    usageError('Provide either a webhook URL or a token, not both');
  }

  const payload = readPayload(options);
  const url = webhookUrl !== '' ? webhookUrl : 'https://slack.com/api/' + options.endpoint;
  const headers = { 'Content-Type': 'application/json; charset=utf-8' };
  if (token !== '') headers.Authorization = 'Bearer ' + token;

  let response;
  try {
    response = await fetch(url, { method: 'POST', headers: headers, body: JSON.stringify(payload) });
  } catch (error) {
    process.stderr.write('Error: could not reach Slack: ' + error.message + '\n');
    process.exit(1);
  }

  if (response.status === 429) {
    const retryAfter = Number(response.headers.get('retry-after') || '1') || 1;
    process.stderr.write('Error: rate limited by Slack (HTTP 429); retry after ' + retryAfter + ' seconds\n');
    process.exit(75);
  }

  const text = await response.text();
  if (!response.ok) {
    process.stderr.write('Error: Slack HTTP ' + response.status + ' ' + response.statusText + '\n' + trimOutput(text, 10) + '\n');
    process.exit(1);
  }

  let data = null;
  try {
    data = JSON.parse(text);
  } catch (error) {
    data = null; // Incoming Webhooks respond with plain text
  }

  if (data !== null && data.ok === false) {
    let message = 'Error: Slack API error: ' + String(data.error);
    if (data.response_metadata && Array.isArray(data.response_metadata.messages) && data.response_metadata.messages.length > 0) {
      message = message + ' (' + data.response_metadata.messages.join('; ') + ')';
    }
    process.stderr.write(message + '\n');
    process.exit(2);
  }

  if (data === null) {
    process.stdout.write('Success: ' + trimOutput(text, 10) + '\n');
  } else {
    process.stdout.write('Success: ' + trimOutput(JSON.stringify(data, null, 2)) + '\n');
  }
}

main().catch(function (error) {
  process.stderr.write('Error: unexpected failure: ' + (error && error.message ? error.message : String(error)) + '\n');
  process.exit(1);
});
`;

function cleanBuild() {
  if (fs.existsSync(SKILL_DIR)) {
    fs.rmSync(SKILL_DIR, { recursive: true, force: true });
  }
  fs.mkdirSync(path.join(SKILL_DIR, 'scripts'), { recursive: true });
  fs.writeFileSync(path.join(SKILL_DIR, 'SKILL.md'), skillMarkdown, 'utf8');
  fs.writeFileSync(path.join(SKILL_DIR, 'scripts', 'slack_request.cjs'), helperSource, 'utf8');
}

function findSkillCreatorScript(fileName) {
  const startDirs = [ROOT, __dirname];
  const checked = new Set();
  for (let s = 0; s < startDirs.length; s = s + 1) {
    let dir = startDirs[s];
    for (let depth = 0; depth < 10; depth = depth + 1) {
      if (checked.has(dir)) break;
      checked.add(dir);
      const candidates = [
        path.join(dir, '.codex', 'skills', 'skill-creator', 'scripts', fileName),
        path.join(dir, 'scripts', fileName)
      ];
      for (let c = 0; c < candidates.length; c = c + 1) {
        try {
          if (fs.statSync(candidates[c]).isFile()) return candidates[c];
        } catch (error) {
          // keep looking
        }
      }
      const parent = path.dirname(dir);
      if (parent === dir) break;
      dir = parent;
    }
  }
  return null;
}

function runNode(scriptPath, args, input) {
  return spawnSync(process.execPath, [scriptPath].concat(args), {
    input: input,
    encoding: 'utf8',
    timeout: 20000
  });
}

function smokeTestHelper(helperPath) {
  const problems = [];
  const t1 = runNode(helperPath, [], '');
  if (t1.error) {
    problems.push('helper no-args run failed to start: ' + t1.error.message);
  } else if (t1.status !== 1 || String(t1.stderr).indexOf('Provide --token') === -1) {
    problems.push('helper no-args run: expected exit 1 with credential hint, got status ' + String(t1.status));
  }
  const t2 = runNode(helperPath, ['--token', 'xoxb-dummy', '--payload', '{bad json'], '');
  if (t2.error) {
    problems.push('helper bad-payload run failed to start: ' + t2.error.message);
  } else if (t2.status !== 1 || String(t2.stderr).indexOf('not valid JSON') === -1) {
    problems.push('helper bad-payload run: expected exit 1 with JSON hint, got status ' + String(t2.status));
  }
  return problems;
}

function tail(text, maxLines) {
  const lines = String(text).split('\n');
  if (lines.length <= maxLines) return String(text);
  return '... (' + (lines.length - maxLines) + ' earlier lines)\n' + lines.slice(-maxLines).join('\n');
}

function main() {
  cleanBuild();

  const mdBytes = fs.statSync(path.join(SKILL_DIR, 'SKILL.md')).size;
  const helperBytes = fs.statSync(path.join(SKILL_DIR, 'scripts', 'slack_request.cjs')).size;
  process.stdout.write('Created skill folder: ' + SKILL_DIR + '\n');
  process.stdout.write('  SKILL.md (' + mdBytes + ' bytes)\n');
  process.stdout.write('  scripts/slack_request.cjs (' + helperBytes + ' bytes)\n');

  const problems = smokeTestHelper(path.join(SKILL_DIR, 'scripts', 'slack_request.cjs'));
  if (problems.length > 0) {
    for (let p = 0; p < problems.length; p = p + 1) {
      process.stderr.write('Smoke test problem: ' + problems[p] + '\n');
    }
    process.exitCode = 1;
    return;
  }
  process.stdout.write('Helper smoke tests passed (usage and invalid-JSON paths).\n');

  const pkgScript = findSkillCreatorScript('package_skill.cjs');
  if (pkgScript === null) {
    process.stdout.write('Note: skill-creator packaging script was not found, so packaging was skipped.\n');
    process.stdout.write('To package later, run: node <skill-creator>/scripts/package_skill.cjs ' + SKILL_DIR + ' <output-dir>\n');
    return;
  }

  const distDir = path.join(ROOT, 'dist');
  fs.mkdirSync(distDir, { recursive: true });
  const run = spawnSync(process.execPath, [pkgScript, SKILL_DIR, distDir], {
    encoding: 'utf8',
    timeout: 120000
  });
  if (run.error) {
    process.stderr.write('Packaging could not run: ' + run.error.message + '\n');
    process.exitCode = 1;
    return;
  }
  const stdout = String(run.stdout || '');
  const stderrText = String(run.stderr || '');
  if (run.status === 0) {
    let artifact = path.join(distDir, SKILL_NAME + '.skill');
    if (!fs.existsSync(artifact)) {
      const found = fs.readdirSync(distDir).filter(function (f) { return f.slice(-6) === '.skill'; })[0];
      if (found) artifact = path.join(distDir, found);
      else artifact = null;
    }
    if (stdout.trim() !== '') process.stdout.write(tail(stdout.trim(), 40) + '\n');
    if (artifact) {
      process.stdout.write('Packaged artifact: ' + artifact + '\n');
    }
    process.stdout.write('Success: created and validated the ' + SKILL_NAME + ' skill.\n');
  } else {
    process.stderr.write('Packaging failed with exit status ' + String(run.status) + ':\n');
    if (stdout.trim() !== '') process.stderr.write(tail(stdout.trim(), 60) + '\n');
    if (stderrText.trim() !== '') process.stderr.write(tail(stderrText.trim(), 60) + '\n');
    process.exitCode = 1;
  }
}

main();

'use strict';

/*
 * build_slack_api_skill.cjs
 *
 * Task-local builder for the requested Slack API skill. Creates the skill
 * folder structure (SKILL.md + scripts/slack_request.cjs) under the current
 * working directory and validates the written artifacts. Pure in-process file
 * writes only: no child processes, no deletion of existing files, no network.
 */

const fs = require('fs');
const path = require('path');

const ROOT = process.cwd();
const SKILL_NAME = 'slack-api';
const SKILL_DIR = path.join(ROOT, SKILL_NAME);
const SKILL_MD_PATH = path.join(SKILL_DIR, 'SKILL.md');
const HELPER_PATH = path.join(SKILL_DIR, 'scripts', 'slack_request.cjs');

const skillMarkdown = String.raw`---
name: slack-api
description: "Send messages, ephemeral messages, thread replies, and reactions, upload files, and read conversations, users, and history through Slack's Web API and Incoming Webhooks. Use when a user asks to automate Slack notifications, query Slack workspace activity, or perform Slack actions with a bot token, user token, or webhook URL."
---

# Slack API

Use Slack's Web API (base URL https://slack.com/api/) and Incoming Webhooks to send and read workspace messages. The bundled script scripts/slack_request.cjs performs one authenticated request so the HTTP code does not get rewritten every time. For multi-step work (resolve an ID, then act, then page through results) call the script once per step.

## Credentials and identifiers

- Bot tokens start with xoxb-; user tokens start with xoxp-. Prefer a bot token with the smallest scope set that still works.
- Read tokens from environment variables (SLACK_TOKEN, SLACK_BOT_TOKEN, SLACK_WEBHOOK_URL) or ask the user. Never hard-code a token in a file and never print a full token.
- Channel IDs start with C..., user IDs with U..., file IDs with F..., team IDs with T....
- A message timestamp (ts) such as 1700000000.123456 identifies a message and doubles as thread_ts for replies.

## Request helper

The helper needs Node.js 18+ and has no third-party dependencies. From the skill folder run:

    node scripts/slack_request.cjs --endpoint chat.postMessage --token "$SLACK_TOKEN" --payload '{"channel":"C1234567890","text":"Hello from a bot"}'

Send through an Incoming Webhook:

    node scripts/slack_request.cjs --webhook-url "$SLACK_WEBHOOK_URL" --payload '{"text":"Hello"}'

Flags: --endpoint (Web API method; default chat.postMessage), --token, --webhook-url, --payload, --payload-file. The payload may also be piped on stdin. On success the script prints Success: followed by trimmed JSON (webhooks answer with plain text). On failure it prints a concise reason and exits non-zero: 1 means usage, transport, or HTTP error; 2 means Slack answered ok:false; 75 means rate limited (retry after the Retry-After seconds Slack reports).

## Common operations

Post a message: chat.postMessage with a channel ID and text. Add link_names: true to turn plain @name and #channel text into links; pass blocks for rich layouts. Plain text is preferred over attachments.

Reply in a thread: set thread_ts to the parent message ts. The response carries reply_ts so later replies can chain.

Send an ephemeral message: chat.postEphemeral with channel, user, and text; only that user sees it.

Update or delete a message: chat.update or chat.delete with channel and ts.

Resolve a channel name to an ID: conversations.list with types "public_channel,private_channel" and limit 1000, paging with cursor from response_metadata.next_cursor until the name matches. Needs channels:read and groups:read. When the app is already in the channel, conversations.info with the channel ID is cheaper.

Find a user: users.lookupByEmail with email (scope users:read.email), or page users.list with limit 1000. User IDs are stable; emails and display names are not.

Read history: conversations.history with channel and limit, plus optional oldest and latest (Unix seconds) to bound the window. Messages carry ts, user, text, and subtype for special kinds; page with next_cursor.

React to a message: reactions.add with channel, name (no colons), and timestamp; reactions.remove works the same way.

Search messages: search.messages with query (scope search:read).

Upload a file: files.upload is deprecated. Call files.getUploadURLExternal with filename and length to get upload_url and file_id, POST the raw bytes to upload_url (for example curl -F file=@report.csv "upload_url"), then call files.completeUploadExternal with files: [{"id":"F...","title":"report.csv"}]. Scope: files:write.

Open a modal: views.open with a view object and the trigger_id from an interaction.

## Message formatting

Slack uses mrkdwn: *bold*, _italic_, ~strikethrough~, and code spans wrapped in the single back-tick character. Mention a user with <@U123...>, reference a channel with <#C123...>, and hyperlink with <https://example.com|link text>. Set link_names: true to link plain @name and #channel text.

## Responses and errors

Web API responses set ok to true or false. Treat ok:false as a failure and surface the error string. Common errors:

- invalid_auth, not_authed, account_inactive: token wrong, revoked, or from a deleted app; ask for a fresh one.
- missing_scope: add the scope to the app and reinstall it in the workspace.
- channel_not_found: use the channel ID, not the name, and confirm the app is in the channel.
- not_in_channel: join public channels with conversations.join or ask an admin to invite the app.
- is_archived: pick a channel that is not archived.
- msg_too_long: text is limited to 40,000 characters; split the message or trim it.
- rate_limited: HTTP 429 with Retry-After; wait that many seconds and retry (the helper exits 75).

Pagination: methods return up to 100 to 1000 records per page (see the method docs) plus response_metadata.next_cursor. Keep paging while the cursor is non-empty and stop once the user's requested volume is reached.

Rate limits: roughly one request per second per method. Delay briefly between calls in a loop and always honor Retry-After on 429.

## Typical multi-step flow

1. Resolve targets first: look up channel and user IDs once and reuse them.
2. Perform the action with IDs.
3. Page only as far as needed and summarize counts instead of dumping full lists.
4. Report what was done: channel, message ts, and any failures.

## Scope checklist

chat:write to send, update, and delete messages; chat:write.customize for bot name and icon overrides; channels:read and groups:read for conversation metadata; im:read and mpim:read for DM and group history; users:read and users:read.email for member lookup; reactions:write; files:write for uploads; search:read for search.messages; incoming-webhook when using a webhook URL.
`;

const helperSource = String.raw`#!/usr/bin/env node
/*
 * slack_request.cjs - one Slack request with LLM-friendly output.
 * Bundled with the slack-api skill. Requires Node.js 18+ (global fetch).
 * No third-party dependencies.
 *
 * Usage:
 *   node scripts/slack_request.cjs --endpoint chat.postMessage \
 *       --token "$SLACK_TOKEN" \
 *       --payload '{"channel":"C1234567890","text":"Hello"}'
 *   node scripts/slack_request.cjs --webhook-url "$SLACK_WEBHOOK_URL" \
 *       --payload '{"text":"Hello"}'
 *   node scripts/slack_request.cjs --endpoint conversations.history \
 *       --token "$SLACK_TOKEN" --payload-file history.json
 *   echo '{"channel":"C1234567890","text":"hi"}' | node scripts/slack_request.cjs \
 *       --token "$SLACK_TOKEN"
 *
 * Exit codes: 0 success; 1 usage/transport/HTTP error; 2 Slack API error
 * (ok:false); 75 rate limited (retry after the reported Retry-After seconds).
 */
'use strict';

const fs = require('fs');
const path = require('path');

function usageError(message) {
  process.stderr.write('Error: ' + message + '\n');
  process.stderr.write('Usage: node slack_request.cjs (--token TOKEN | --webhook-url URL) [--endpoint METHOD] (--payload JSON | --payload-file FILE | stdin)\n');
  process.exit(1);
}

function parseArgs(argv) {
  const options = { endpoint: 'chat.postMessage', payload: null, payloadFile: null, token: null, webhookUrl: null };
  for (let i = 0; i < argv.length; i = i + 1) {
    const flag = argv[i];
    const nextValue = function () {
      i = i + 1;
      if (i >= argv.length) usageError('Missing value for ' + flag);
      return argv[i];
    };
    if (flag === '--endpoint') options.endpoint = nextValue();
    else if (flag === '--token') options.token = nextValue();
    else if (flag === '--webhook-url') options.webhookUrl = nextValue();
    else if (flag === '--payload') options.payload = nextValue();
    else if (flag === '--payload-file') options.payloadFile = nextValue();
    else usageError('Unknown flag: ' + flag);
  }
  return options;
}

function readPayload(options) {
  if (options.payload !== null && options.payloadFile !== null) {
    usageError('Use either --payload or --payload-file, not both');
  }
  let raw = options.payload;
  if (options.payloadFile !== null) {
    try {
      raw = fs.readFileSync(path.resolve(options.payloadFile), 'utf8');
    } catch (error) {
      usageError('Could not read payload file: ' + error.message);
    }
  } else if (raw === null) {
    if (process.stdin.isTTY) {
      usageError('No payload provided; pass --payload JSON, --payload-file FILE, or pipe JSON on stdin');
    }
    try {
      raw = fs.readFileSync(0, 'utf8');
    } catch (error) {
      usageError('Could not read stdin payload: ' + error.message);
    }
  }
  if (raw === null || raw.trim().length === 0) usageError('Payload is empty');
  try {
    return JSON.parse(raw);
  } catch (error) {
    usageError('Payload is not valid JSON: ' + error.message);
  }
}

function trimOutput(text, maxLines, maxChars) {
  if (maxLines === undefined) maxLines = 60;
  if (maxChars === undefined) maxChars = 6000;
  const allLines = String(text).split('\n');
  let result = allLines.slice(0, maxLines).join('\n');
  if (allLines.length > maxLines) {
    result = result + '\n... (' + (allLines.length - maxLines) + ' more lines)';
  }
  if (result.length > maxChars) {
    result = result.slice(0, maxChars) + '\n... (output truncated)';
  }
  return result;
}

async function main() {
  const options = parseArgs(process.argv.slice(2));
  const token = options.token || process.env.SLACK_TOKEN || process.env.SLACK_BOT_TOKEN || '';
  const webhookUrl = options.webhookUrl || process.env.SLACK_WEBHOOK_URL || '';

  if (token === '' && webhookUrl === '') {
    usageError('Provide --token (or set SLACK_TOKEN) for the Web API, or --webhook-url (or set SLACK_WEBHOOK_URL) for a webhook');
  }
  if (token !== '' && webhookUrl !== '') {
    usageError('Provide either a webhook URL or a token, not both');
  }

  const payload = readPayload(options);
  const url = webhookUrl !== '' ? webhookUrl : 'https://slack.com/api/' + options.endpoint;
  const headers = { 'Content-Type': 'application/json; charset=utf-8' };
  if (token !== '') headers.Authorization = 'Bearer ' + token;

  let response;
  try {
    response = await fetch(url, { method: 'POST', headers: headers, body: JSON.stringify(payload) });
  } catch (error) {
    process.stderr.write('Error: could not reach Slack: ' + error.message + '\n');
    process.exit(1);
  }

  if (response.status === 429) {
    const retryAfter = Number(response.headers.get('retry-after') || '1') || 1;
    process.stderr.write('Error: rate limited by Slack (HTTP 429); retry after ' + retryAfter + ' seconds\n');
    process.exit(75);
  }

  const text = await response.text();
  if (!response.ok) {
    process.stderr.write('Error: Slack HTTP ' + response.status + ' ' + response.statusText + '\n' + trimOutput(text, 10) + '\n');
    process.exit(1);
  }

  let data = null;
  try {
    data = JSON.parse(text);
  } catch (error) {
    data = null; // Incoming Webhooks respond with plain text
  }

  if (data !== null && data.ok === false) {
    let message = 'Error: Slack API error: ' + String(data.error);
    if (data.response_metadata && Array.isArray(data.response_metadata.messages) && data.response_metadata.messages.length > 0) {
      message = message + ' (' + data.response_metadata.messages.join('; ') + ')';
    }
    process.stderr.write(message + '\n');
    process.exit(2);
  }

  if (data === null) {
    process.stdout.write('Success: ' + trimOutput(text, 10) + '\n');
  } else {
    process.stdout.write('Success: ' + trimOutput(JSON.stringify(data, null, 2)) + '\n');
  }
}

main().catch(function (error) {
  process.stderr.write('Error: unexpected failure: ' + (error && error.message ? error.message : String(error)) + '\n');
  process.exit(1);
});
`;

function writeSkillFiles() {
  fs.mkdirSync(path.join(SKILL_DIR, 'scripts'), { recursive: true });
  fs.writeFileSync(SKILL_MD_PATH, skillMarkdown, 'utf8');
  fs.writeFileSync(HELPER_PATH, helperSource, 'utf8');
}

function validateArtifacts() {
  const problems = [];
  const md = fs.readFileSync(SKILL_MD_PATH, 'utf8');
  const helper = fs.readFileSync(HELPER_PATH, 'utf8');

  if (md.indexOf('name: ' + SKILL_NAME) === -1) {
    problems.push('SKILL.md frontmatter is missing name: ' + SKILL_NAME);
  }
  if (md.indexOf('description:') === -1) {
    problems.push('SKILL.md frontmatter is missing description');
  }
  if (md.indexOf('scripts/slack_request.cjs') === -1) {
    problems.push('SKILL.md does not reference the bundled helper script');
  }
  if (md.indexOf('TODO') !== -1) {
    problems.push('SKILL.md still contains TODO markers');
  }
  if (md.trim().length === 0) {
    problems.push('SKILL.md is empty');
  }
  if (helper.indexOf('#!/usr/bin/env node') !== 0) {
    problems.push('helper script is missing its shebang');
  }
  if (helper.indexOf('https://slack.com/api/') === -1) {
    problems.push('helper script does not target the Slack Web API');
  }
  if (helper.trim().length === 0) {
    problems.push('helper script is empty');
  }
  return problems;
}

function main() {
  writeSkillFiles();

  const mdBytes = fs.statSync(SKILL_MD_PATH).size;
  const helperBytes = fs.statSync(HELPER_PATH).size;

  const problems = validateArtifacts();
  if (problems.length > 0) {
    for (let p = 0; p < problems.length; p = p + 1) {
      process.stderr.write('Validation problem: ' + problems[p] + '\n');
    }
    process.exitCode = 1;
    return;
  }

  process.stdout.write('Created skill folder: ' + SKILL_DIR + '\n');
  process.stdout.write('  SKILL.md (' + mdBytes + ' bytes)\n');
  process.stdout.write('  scripts/slack_request.cjs (' + helperBytes + ' bytes)\n');
  process.stdout.write('Success: the ' + SKILL_NAME + ' skill was created and validated.\n');
}

main();

