function readPayload(options) {
  if (options.payload !== null && options.payloadFile !== null) {
    usageError('Use either --payload or --payload-file, not both');
  }
  let raw = options.payload;
  if (options.payloadFile !== null) {
    try {
      raw = fs.readFileSync(path.resolve(options.payloadFile), 'utf8');
    } catch (error) {
      usageError('Could not read payload file: ' + error.message);
    }
  } else if (raw === null) {
    if (process.stdin.isTTY) {
      usageError('No payload provided; pass --payload JSON, --payload-file FILE, or pipe JSON on stdin');
    }
    try {
      raw = fs.readFileSync(0, 'utf8');
    } catch (error) {
      usageError('Could not read stdin payload: ' + error.message);
    }
  }
  if (raw === null || raw.trim().length === 0) usageError('Payload is empty');
  try {
    return JSON.parse(raw);
  } catch (error) {
    usageError('Payload is not valid JSON: ' + error.message);
  }
}

function trimOutput(text, maxLines, maxChars) {
  if (maxLines === undefined) maxLines = 60;
  if (maxChars === undefined) maxChars = 6000;
  const allLines = String(text).split('\n');
  let result = allLines.slice(0, maxLines).join('\n');
  if (allLines.length > maxLines) {
    result = result + '\n... (' + (allLines.length - maxLines) + ' more lines)';
  }
  if (result.length > maxChars) {
    result = result.slice(0, maxChars) + '\n... (output truncated)';
  }
  return result;
}

async function main() {
  const options = parseArgs(process.argv.slice(2));
  const token = options.token || process.env.SLACK_TOKEN || process.env.SLACK_BOT_TOKEN || '';
  const webhookUrl = options.webhookUrl || process.env.SLACK_WEBHOOK_URL || '';

  if (token === '' && webhookUrl === '') {
    usageError('Provide --token (or set SLACK_TOKEN) for the Web API, or --webhook-url (or set SLACK_WEBHOOK_URL) for a webhook');
  }
  if (token !== '' && webhookUrl !== '') {
    usageError('Provide either a webhook URL or a token, not both');
  }

  const payload = readPayload(options);
  const url = webhookUrl !== '' ? webhookUrl : 'https://slack.com/api/' + options.endpoint;
  const headers = { 'Content-Type': 'application/json; charset=utf-8' };
  if (token !== '') headers.Authorization = 'Bearer ' + token;

  let response;
  try {
    response = await fetch(url, { method: 'POST', headers: headers, body: JSON.stringify(payload) });
  } catch (error) {
    process.stderr.write('Error: could not reach Slack: ' + error.message + '\n');
    process.exit(1);
  }

  if (response.status === 429) {
    const retryAfter = Number(response.headers.get('retry-after') || '1') || 1;
    process.stderr.write('Error: rate limited by Slack (HTTP 429); retry after ' + retryAfter + ' seconds\n');
    process.exit(75);
  }

  const text = await response.text();
  if (!response.ok) {
    process.stderr.write('Error: Slack HTTP ' + response.status + ' ' + response.statusText + '\n' + trimOutput(text, 10) + '\n');
    process.exit(1);
  }

  let data = null;
  try {
    data = JSON.parse(text);
  } catch (error) {
    data = null; // Incoming Webhooks respond with plain text
  }

  if (data !== null && data.ok === false) {
    let message = 'Error: Slack API error: ' + String(data.error);
    if (data.response_metadata && Array.isArray(data.response_metadata.messages) && data.response_metadata.messages.length > 0) {
      message = message + ' (' + data.response_metadata.messages.join('; ') + ')';
    }
    process.stderr.write(message + '\n');
    process.exit(2);
  }

  if (data === null) {
    process.stdout.write('Success: ' + trimOutput(text, 10) + '\n');
  } else {
    process.stdout.write('Success: ' + trimOutput(JSON.stringify(data, null, 2)) + '\n');
  }
}

main().catch(function (error) {
  process.stderr.write('Error: unexpected failure: ' + (error && error.message ? error.message : String(error)) + '\n');
  process.exit(1);
});
```

The helper intentionally never logs the Authorization header or the token value. After writing the file, run node --check on it once to confirm it was copied intact, then use the commands in the Request helper section.
